import{_ as t,o,c as a,a3 as r}from"./chunks/framework.cNy3aYYk.js";const m=JSON.parse('{"title":"Customer Portal Module","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Customer Portal Module | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/user-guide/customer-portal-overview"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Customer Portal Module | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/user-guide/customer-portal-overview"}]]},"headers":[],"relativePath":"user-guide/customer-portal-overview.md","filePath":"user-guide/customer-portal-overview.md","lastUpdated":1791283578000}'),i={name:"user-guide/customer-portal-overview.md"};function s(l,e,d,n,c,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="customer-portal-module" tabindex="-1">Customer Portal Module <a class="header-anchor" href="#customer-portal-module" aria-label="Permalink to &quot;Customer Portal Module&quot;">​</a></h1><p>Free <strong>Operations</strong> Marketplace module that gives invited Contacts a separate login to view their invoices, payments, quotations, and contracts, and to submit/track Help Desk tickets. Staff remain in the workspace SPA; customers use the isolated portal shell (<code>/#/portal/*</code>).</p><blockquote><p><strong>Not Vendor Portal / not Stripe billing portal</strong></p><p>This is an <strong>end-customer</strong> account hub for CRM Contacts. Vendor self-service stays parked. Stripe/Creem “customer portal” links are SaaS subscription billing for the workspace itself — unrelated.</p></blockquote><h2 id="guides" tabindex="-1">Guides <a class="header-anchor" href="#guides" aria-label="Permalink to &quot;Guides&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Audience</th><th>Document</th></tr></thead><tbody><tr><td>Operators / workspace users</td><td><a href="/user-guide/customer-portal">customer-portal.md</a></td></tr><tr><td>Engineers</td><td><a href="/developer-guide/customer-portal">customer-portal.md</a></td></tr><tr><td>Production / ops</td><td><a href="/deployment/customer-portal">customer-portal.md</a></td></tr><tr><td>Production readiness</td><td><a href="/deployment/customer-portal-1-0-0-production-readiness">customer-portal-1-0-0-production-readiness.md</a></td></tr><tr><td>Tenant API</td><td><a href="/api/tenant-v1-customer-portal">../api/tenant-v1-customer-portal.md</a></td></tr></tbody></table><h2 id="capabilities-1-0-0" tabindex="-1">Capabilities (1.0.0) <a class="header-anchor" href="#capabilities-1-0-0" aria-label="Permalink to &quot;Capabilities (1.0.0)&quot;">​</a></h2><ul><li>Invite-only portal accounts linked 1:1 to a Contact (email + password; no open self-registration)</li><li>Separate Sanctum guard (<code>portal-api</code>) — never staff <code>User</code> / Spatie roles</li><li>Staff: Operations → Customer Portal list; Contact record invite / resend / disable / enable</li><li>Customer SPA: login, forgot/reset password, accept invite, dashboard</li><li>Soft-gated sections: Invoices, Payments, Quotations, Contracts, Support (Help Desk)</li><li>Document PDF download; quotation/contract acceptance-link from portal (existing public accept pages)</li><li>Help Desk: customer creates tickets (contact stamped server-side) and adds notes</li></ul><h2 id="permissions-staff" tabindex="-1">Permissions (staff) <a class="header-anchor" href="#permissions-staff" aria-label="Permalink to &quot;Permissions (staff)&quot;">​</a></h2><p><code>customer-portal.view</code> · <code>invite</code> · <code>manage</code></p><table tabindex="0"><thead><tr><th>Role</th><th>Grants</th></tr></thead><tbody><tr><td><strong>admin</strong></td><td>All</td></tr><tr><td><strong>manager</strong></td><td><code>view</code>, <code>invite</code>, <code>manage</code></td></tr><tr><td><strong>staff</strong></td><td><code>view</code>, <code>invite</code></td></tr></tbody></table><h2 id="licensing" tabindex="-1">Licensing <a class="header-anchor" href="#licensing" aria-label="Permalink to &quot;Licensing&quot;">​</a></h2><ul><li>Catalog slug: <code>customer-portal</code>, category <code>operations</code>, version <strong>1.0.0</strong></li><li><code>is_default_included = false</code>, <code>is_billable = false</code></li><li><strong>Hard dependency:</strong> <code>contacts</code></li><li>Soft: <code>invoices</code>, <code>payments</code>, <code>quotations</code>, <code>contracts</code>, <code>help-desk</code> (section hidden / API 403 when not entitled)</li></ul><h2 id="explicitly-deferred" tabindex="-1">Explicitly deferred <a class="header-anchor" href="#explicitly-deferred" aria-label="Permalink to &quot;Explicitly deferred&quot;">​</a></h2><ul><li>Projects / tasks visibility</li><li>Magic-link passwordless login</li><li>Public Knowledge Base</li><li>Vendor / reseller portals</li><li>Online payment checkout</li><li>Portal 2FA / passkeys</li></ul>',14)])])}const h=t(i,[["render",s]]);export{m as __pageData,h as default};
